{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "Surface Coating of Plastic Parts and Products",
      "criteria": [
        {
          "criterion": "if the activity is the application of a coating to a plastic substrate (i.e., coating application) or an associated activity that is directly related to the application of a coating, then subject",
          "citations": [
            "40 CFR 63.4481(a)(1)"
          ]
        },
        {
          "criterion": "if the material applied is an adhesive (a chemical substance applied for the purpose of bonding two surfaces together), then subject",
          "citations": [
            "40 CFR 63.4581"
          ]
        },
        {
          "criterion": "if the activity is only the use of a cleaning material (surface preparation) that is not directly related to the application of a coating, then not subject",
          "citations": [
            "40 CFR 63.4481(a)(1)",
            "40 CFR 63.4581"
          ]
        },
        {
          "criterion": "if the facility uses 378 liters (100 gallons) per year or more of coatings that contain HAP in the surface coating of plastic parts and products and the source is a major source (or located at a major source), then subject",
          "citations": [
            "40 CFR 63.4481(b)"
          ]
        },
        {
          "criterion": "if the surface coating or coating operation meets any of the exclusion criteria in paragraphs (c)(1) through (c)(17) of § 63.4481 (for example, uses only materials that contain no organic HAP), then not subject",
          "citations": [
            "40 CFR 63.4481(c)"
          ]
        },
        {
          "criterion": "if the activity is part of the affected source as defined (all coating operations; all storage containers and mixing vessels for coatings/thinners/additives/cleaning materials; conveying equipment for those materials; and storage/conveying equipment for waste from coating operations), then subject",
          "citations": [
            "40 CFR 63.4482(b)(1)",
            "40 CFR 63.4482(b)(2)",
            "40 CFR 63.4482(b)(3)",
            "40 CFR 63.4482(b)(4)"
          ]
        },
        {
          "criterion": "if you choose the compliant material option and each coating's organic HAP content and each thinner/additive/cleaning material meet the mass-fraction/analysis procedures and limits in § 63.4541, then the coating operation is not required to meet the operating limits or work practice standards in §§ 63.4492 and 63.4493",
          "citations": [
            "40 CFR 63.4541(a)",
            "40 CFR 63.4541(b)",
            "40 CFR 63.4541(d)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Is the methylene-chloride application intended to bond (solvent weld) parts (i.e., purpose = bonding) or solely to clean/prepare the surface?",
    "Does the applied material leave a solid film or dry coating on the substrate after evaporation, or is nothing with solids left behind?",
    "Does the methylene-chloride application meet your facility's/your interpretation of the definition of an 'adhesive' (chemical applied to bond surfaces) or of a 'coating' per § 63.4581?",
    "Is the methylene-chloride step directly related to the application of a separate coating (i.e., an associated activity) or independent (purely welding/assembly)?",
    "How many liters (or gallons) per year of materials that qualify as 'coatings' containing HAP (not counting non-HAP coatings per § 63.4581) will be used at the affected source (current + after adding six lines)?",
    "Is the facility a major source of HAP (potential to emit ≥ 9.07 Mg (10 tons) of any single HAP or ≥ 22.68 Mg (25 tons) total HAP per year)?",
    "Do any of the exclusions in § 63.4481(c)(1)–(17) apply to this operation (e.g., uses only materials with no organic HAP; research/lab facility; extruding plastic onto parts; other listed exemptions)?",
    "Is the solvent-welding operation located within the collection of components defined as the affected source (include storage, mixing, conveyance, and waste handling associated with the operation)?",
    "For materials used: obtain manufacturer formulation data or test results (Method 311, Method 24 or approved alternatives) to determine mass fraction of organic HAP and mass fraction of coating solids per § 63.4541(a)–(c).",
    "If relying on the compliant material option, can you document that each coating's organic HAP content is ≤ the applicable emission limit in § 63.4490 and that each thinner/additive/cleaning material contains no organic HAP, using the procedures in § 63.4541?",
    "Recordkeeping: assemble documentation for initial compliance notifications and records per subpart PPPP (identify coating operations and method used to determine organic HAP and solids content)."
  ]
}

{
  "candidates": [
    {
      "subpart": "Subpart M",
      "title": "National Perchloroethylene Dry Cleaning",
      "criteria": [
        {
          "criterion": "If the facility uses perchloroethylene then the owner or operator is subject to this subpart.",
          "citations": [
            "40 CFR 63.320(a)"
          ]
        },
        {
          "criterion": "If the dry cleaning machine is coin-operated then the owner or operator is not subject to the requirements of this subpart.",
          "citations": [
            "40 CFR 63.320(j)"
          ]
        },
        {
          "criterion": "If a dry cleaning system is located in a building with a residence then after December 21, 2020 the owner or operator shall eliminate any emission of perchloroethylene from that dry cleaning system.",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ]
        },
        {
          "criterion": "If a dry cleaning system was installed or relocated after December 21, 2005 and is located in a building with a residence then the owner or operator shall eliminate any emission of perchloroethylene from that dry cleaning system.",
          "citations": [
            "40 CFR 63.322(o)(4)"
          ]
        },
        {
          "criterion": "If a dry cleaning system commenced construction or reconstruction on or after December 21, 2005 but before July 13, 2006 and is located in a building with a residence then the owner or operator shall comply with the additional requirements at §63.322(o)(5)(ii)(A)–(C) (vapor barrier enclosure; refrigerated condenser plus carbon adsorber immediately prior to door opening; and weekly inspections) in addition to other applicable requirements.",
          "citations": [
            "40 CFR 63.320(b)(2)(ii)",
            "40 CFR 63.322(o)(5)(ii)"
          ]
        },
        {
          "criterion": "If the dry cleaning facility emits or has the potential to emit more than 9.1 megagrams per year (10 tons per year) of perchloroethylene, or meets the numeric perchloroethylene consumption criteria in §63.320(g)(1) or (g)(2), then the facility is a major source (if not, then it is an area source).",
          "citations": [
            "40 CFR 63.320(g)",
            "40 CFR 63.320(h)"
          ]
        },
        {
          "criterion": "If the facility's total yearly perchloroethylene consumption determined according to §63.323(d) is less than 530 liters (140 gallons) for facilities with only dry-to-dry machines or less than 760 liters (200 gallons) for facilities with only transfer-machine systems then certain existing systems installed in specified date ranges may be exempt from specified provisions of §§63.322, 63.323, and 63.324 as described in §63.320(d) and (e).",
          "citations": [
            "40 CFR 63.320(d)",
            "40 CFR 63.320(e)",
            "40 CFR 63.323(d)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Does the facility use perchloroethylene (PCE) at any time?",
    "Is any dry cleaning machine coin-operated (customer loads/starts the machine)?",
    "Is there a residence located in the same building as the dry cleaning machine (note: a vacant residence still counts per notification requirement)?",
    "What is the exact date the dry cleaning machine was constructed, reconstructed, installed, or (if applicable) relocated (to determine which compliance dates and paragraphs apply)?",
    "Is the machine a dry-to-dry machine or a transfer machine system?",
    "Was the machine installed or relocated after December 21, 2005, or did construction/reconstruction commence between December 21, 2005 and July 13, 2006?",
    "Calculate total PCE purchased for each of the prior 12 months and sum per §63.323(d) to determine yearly PCE consumption (keep purchase receipts/logs).",
    "Does the yearly PCE consumption exceed 530 L (140 gal), 760 L (200 gal), 6,800 L (1,800 gal), or 8,000 L (2,100 gal) thresholds used in §63.320(d),(e),(g)?",
    "Based on emissions or consumption thresholds, is the facility a major source (>9.1 Mg/yr or per §63.320(g) criteria) or an area source?",
    "If located in a building with a residence, verify whether compliance demonstration under §63.320(b)(2)(ii) (systems commenced Dec 21, 2005–July 13, 2006) might apply (check construction date and building/residence status).",
    "Maintain and be able to produce on site PCE purchase receipts and the monthly/yearly consumption log per §63.324(d) (records retained for 5 years).",
    "If claiming any exemption for older machines per §63.320(d)/(e), document the machine installation dates and the facility PCE consumption calculation used to justify the exemption."
  ]
}

{
  "candidates": [
    {
      "subpart": "XXXXXX",
      "title": "Metal Fabrication and Finishing Area Sources",
      "criteria": [
        {
          "criterion": "If you own or operate an area source that is primarily engaged in operations in one of the nine metal fabrication and finishing source categories listed in § 63.11514(a)(1) through (9) then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11514(a)",
            "40 CFR 63.11514(a)(1)"
          ]
        },
        {
          "criterion": "If you use materials that contain or have the potential to emit metal fabrication or finishing HAP (MFHAP) as defined in § 63.11522 (cadmium, chromium, lead, manganese, nickel at the concentrations specified) then the provisions of this subpart apply to the affected source types listed in § 63.11514(b)(1) through (5).",
          "citations": [
            "40 CFR 63.11514(b)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If your facility's production of products listed in one of the nine source category descriptions represents at least 50 percent of the production at the facility over the previous continuous 12 months then the facility is 'primarily engaged' in that source category for purposes of applicability.",
          "citations": [
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If all or part of the operations are limited to research or laboratory facilities, tool or equipment repair, facility maintenance, or quality control activities as defined in § 63.11522 then those operations are not subject to this subpart.",
          "citations": [
            "40 CFR 63.11514(e)",
            "40 CFR 63.11514(f)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If the operations are performed on site at installations owned or operated by the Armed Forces, the National Aeronautics and Space Administration, or the National Nuclear Security Administration, or if the operations produce military munitions as defined in § 63.11522, then this subpart does not apply to those operations.",
          "citations": [
            "40 CFR 63.11514(g)",
            "40 CFR 63.11514(h)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If you perform machining, dry abrasive blasting, dry grinding and dry polishing with machines, spray painting, or welding operations that use materials containing MFHAP or have the potential to emit MFHAP then those operations qualify as the corresponding affected source types described in § 63.11514(b)(1) through (5).",
          "citations": [
            "40 CFR 63.11514(b)(1)",
            "40 CFR 63.11514(b)(2)",
            "40 CFR 63.11514(b)(3)",
            "40 CFR 63.11514(b)(4)",
            "40 CFR 63.11514(b)(5)"
          ]
        },
        {
          "criterion": "If a welding affected source uses 2,000 pounds or more per year of welding rod containing one or more MFHAP (calculated on a rolling 12-month basis) then the owner or operator must demonstrate that management practices or fume control measures are being implemented by complying with the requirements in § 63.11516(f)(3) through (8).",
          "citations": [
            "40 CFR 63.11516(f)"
          ]
        },
        {
          "criterion": "If you commenced construction or reconstruction of the affected source before April 3, 2008 then the affected source is an existing source, and if you commenced construction or reconstruction on or after April 3, 2008 then the affected source is a new source.",
          "citations": [
            "40 CFR 63.11514(c)",
            "40 CFR 63.11514(d)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm that the facility is an 'area source' of HAP (not a major source).",
    "Determine whether the facility is 'primarily engaged' (≥50% of production over the previous continuous 12 months) in any one of the nine metal fabrication and finishing source categories listed in § 63.11514(a)(1)-(9) (identify which category from Table 1).",
    "Identify which operations are performed at the facility: machining, welding, dry abrasive blasting, dry grinding/dry polishing with machines, spray-applied painting, or other metal fabrication/finishing activities.",
    "For each material, review formulation data/MSDS to determine whether it contains MFHAP: cadmium, chromium, lead, or nickel ≥0.1% by weight (as the metal) or manganese ≥1.0% by weight (as the metal).",
    "For welding: track rolling 12-month usage (pounds) of welding rod that contains any MFHAP to see if it meets or exceeds 2,000 lb/yr.",
    "If spray painting is performed, determine whether paints are spray-applied (hand-held spray, HVLP, electrostatic, airless, etc.) and whether the paints contain MFHAP; document spray booth/room configuration and filter technology if applicable.",
    "If dry abrasive blasting is performed, determine whether blasting is totally enclosed/unvented or vented, whether blast media contain MFHAP, and the size of items blasted (greater than 8 ft in any dimension).",
    "Determine whether any operations at the facility fall under the exclusions: research/laboratory, tool/equipment repair, facility maintenance, or quality control (per definitions in § 63.11522).",
    "Determine whether the facility or operations are on installations owned/operated by the Armed Forces, NASA, or NNSA, or whether operations produce military munitions.",
    "Document the date construction or reconstruction of any affected source commenced to classify sources as new (on/after April 3, 2008) or existing (before April 3, 2008).",
    "Collect and retain supporting records for applicability determinations (equipment lists, processes included in affected source, changes and dates), MSDS/formulation data, production accounting used to establish 'primarily engaged' (showing percent by volume/linear foot/square foot or other metric), and rolling 12-month welding rod usage records."
  ]
}

{
  "candidates": [
    {
      "subpart": "CCCCCC",
      "title": "Gasoline Dispensing Facilities (GDF) (Subpart CCCCCC)",
      "criteria": [
        {
          "criterion": "if the facility is a gasoline dispensing facility (GDF) located at an area source, then the affected source includes each gasoline storage tank at that GDF and is subject to this subpart",
          "citations": [
            "40 CFR 63.11111(a)",
            "40 CFR 63.11112(a)"
          ]
        },
        {
          "criterion": "if your GDF has a monthly throughput of less than 10,000 gallons of gasoline, then the affected source is subject to the requirements in § 63.11116 of this subpart",
          "citations": [
            "40 CFR 63.11111(b)"
          ]
        },
        {
          "criterion": "if a storage tank is not in gasoline service (for example it stores diesel or a fuel that does not meet the gasoline definition), then that tank is not covered by this subpart",
          "citations": [
            "40 CFR 63.11112(a)",
            "40 CFR 63.11132"
          ]
        },
        {
          "criterion": "if an item is the equipment used for the refueling of motor vehicles, then that equipment is not covered by this subpart",
          "citations": [
            "40 CFR 63.11112(a)"
          ]
        },
        {
          "criterion": "if an affected source's throughput ever exceeds an applicable throughput threshold, then the affected source will remain subject to the requirements for sources above the threshold even if throughput later falls below the threshold",
          "citations": [
            "40 CFR 63.11111(i)"
          ]
        },
        {
          "criterion": "if the facility dispenses gasoline into the fuel tanks of motor vehicles, nonroad vehicles, or nonroad engines, then the facility meets the definition of a gasoline dispensing facility (GDF) for this subpart",
          "citations": [
            "40 CFR 63.11132"
          ]
        },
        {
          "criterion": "if dispensing from a fixed gasoline storage tank to a portable gasoline tank is performed for on-site delivery and subsequent dispensing into a motor vehicle, then that activity is subject only to § 63.11116",
          "citations": [
            "40 CFR 63.11111(j)",
            "40 CFR 63.11116"
          ]
        }
      ]
    },
    {
      "subpart": "BBBBBB",
      "title": "Area Source Standards for Bulk Gasoline Terminals, Pipeline Breakout Stations, Pipeline Pumping Stations, and Bulk Gasoline Plants (Subpart BBBBBB)",
      "criteria": [
        {
          "criterion": "if you own or operate a bulk gasoline terminal, pipeline breakout station, pipeline pumping station, or bulk gasoline plant as identified in § 63.11081(a), then you are subject to this subpart",
          "citations": [
            "40 CFR 63.11081(a)"
          ]
        },
        {
          "criterion": "if gasoline storage tanks are located at an affected source identified in § 63.11081(a)(1)-(4) but are used only for dispensing gasoline in a manner consistent with tanks located at a gasoline dispensing facility as defined in § 63.11132, then those tanks are not subject to this subpart and must comply with subpart CCCCCC instead",
          "citations": [
            "40 CFR 63.11081(c)",
            "40 CFR 63.11132"
          ]
        },
        {
          "criterion": "if a bulk gasoline plant's annual average gasoline throughput reaches or exceeds 4,000 gallons per day, then the bulk gasoline plant will remain subject to the vapor balancing requirements even if the annual average throughput later falls below 4,000 gallons per day",
          "citations": [
            "40 CFR 63.11081(f)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "For each tank, verify the fuel type stored (gasoline vs diesel) and for gasoline confirm Reid vapor pressure ≥ 27.6 kPa to meet the subpart's gasoline definition.",
    "Determine whether the facility/practical location dispenses gasoline into the fuel tanks of motor vehicles, nonroad vehicles, or nonroad engines (i.e., whether it functions as a GDF per § 63.11132).",
    "Calculate the monthly throughput for all gasoline storage tanks at each separate GDF using the method in § 63.11111(h)/§ 63.11132 (current day plus prior 364 days summed and divided by 12) and document results.",
    "Confirm whether the tanks are 'storage tanks' in gasoline service (covered) versus only 'equipment used for refueling' (which the subpart excludes from coverage).",
    "Check whether the tanks are part of a bulk gasoline terminal, pipeline breakout/pumping station, or bulk gasoline plant as listed in § 63.11081(a).",
    "If subject to bulk-plant definitions, verify whether the tanks are used only in a manner consistent with GDF tanks (if so, they are excluded from subpart BBBBBB per § 63.11081(c)).",
    "Verify whether any throughput ever exceeded applicable threshold levels (and if so, gather records showing the dates and amounts, because exceeding a threshold can make the source remain subject to higher-tier requirements per § 63.11111(i) and § 63.11081(f)).",
    "Assemble and retain throughput records (and any required supporting documentation) so they can be produced within 24 hours upon request by the Administrator as required for area-source GDFs (§ 63.11116(b) and § 63.11111(e)/(j))."
  ]
}

{
  "candidates": [
    {
      "subpart": "HHHHHH",
      "title": "Area source paint stripping and miscellaneous surface coating operations (Subpart HHHHHH)",
      "criteria": [
        {
          "criterion": "if you operate an area source of HAP and perform spray application of coatings that contain the target HAP to a plastic and/or metal substrate on a part or product (not motor vehicles or mobile equipment), then subject to this subpart",
          "citations": [
            "40 CFR 63.11170(a)(3)",
            "40 CFR 63.11169(c)"
          ]
        },
        {
          "criterion": "if you operate an area source of HAP and perform spray application of coatings to motor vehicles and mobile equipment (excluding spray coating that meets the definition of facility maintenance), then subject to this subpart",
          "citations": [
            "40 CFR 63.11170(a)(2)",
            "40 CFR 63.11180"
          ]
        },
        {
          "criterion": "if a spray-applied coating contains any individual target HAP at or above the specified thresholds (≥0.1 percent by mass for carcinogenic target HAP such as cadmium, chromium, lead, or nickel; ≥1.0 percent by mass for manganese), then that coating is a target HAP containing coating",
          "citations": [
            "40 CFR 63.11180"
          ]
        },
        {
          "criterion": "if your source is not an area source of HAP (for example, is a major source or is located at or part of a major source), then you are not the area source category addressed by this subpart",
          "citations": [
            "40 CFR 63.11170(a)",
            "40 CFR 63.11170(b)"
          ]
        },
        {
          "criterion": "if the surface coating or paint stripping activity meets one of the exclusions (research and laboratory activities, quality control activities, facility maintenance, certain Federal/military installations, or activities covered under another area source NESHAP), then that activity is not covered by this subpart",
          "citations": [
            "40 CFR 63.11169(d)",
            "40 CFR 63.11180"
          ]
        },
        {
          "criterion": "if multiple surface coating operations and related equipment are located at the same source and under common control (mixing rooms, spray booths, spray guns, gun cleaning equipment, solvent handling, etc.), then they together constitute the affected source for determining applicability",
          "citations": [
            "40 CFR 63.11171(b)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Determine whether your facility is an area source (total HAP emissions potential < major source thresholds) or is a major source / part of a major source (see 40 CFR 63.11170(b))",
    "Confirm whether the polyurea line uses spray-applied coating methods (hand-held or booth spray atomizing devices) as defined in §63.11180",
    "For the polyurea line, obtain supplier formulation data/MSDS and calculate the target HAP concentration in the coating as applied (not just in purchased components) to verify whether any individual target HAP meets or exceeds ≥0.1% by mass (Cr, Cd, Pb, Ni) or ≥1.0% by mass (Mn)",
    "Determine whether the parts coated on the polyurea line are motor vehicles or mobile equipment (motor vehicle/mobile equipment surface coating) or miscellaneous parts/products (metal/plastic parts not motor vehicles)",
    "Determine whether the polyurea line activity is performed as facility maintenance, research and laboratory activities, or quality control activities (which are excluded) per the definitions in §63.11180 and exclusions in §63.11169(d)",
    "Determine whether the polyurea line is part of the same affected source as other coating lines at your facility (mixing rooms, booths, spray guns, cleaning equipment, solvent handling) so that coatings used on other lines could affect overall source applicability per §63.11171(b)",
    "If you coat motor vehicles/mobile equipment and you claim you spray apply no target HAP-containing coatings, prepare the petition or (on/after May 9, 2023) the notification to the Administrator and retain on-site records describing the coatings sprayed as allowed in §63.11170(a)(2)",
    "Verify whether any other area source NESHAP covers the same coating activities at your facility (to assess the exclusion in §63.11169(d)(6))"
  ]
}

{
  "candidates": [
    {
      "subpart": "YYYY",
      "title": "Subpart YYYY",
      "criteria": [
        {
          "criterion": "if your stationary combustion turbine is a new or reconstructed lean premix gas-fired stationary combustion turbine then you must comply with the emission limitations and operating limitations in Table 1 and Table 2 of this subpart",
          "citations": [
            "40 CFR 63.6100"
          ]
        },
        {
          "criterion": "if your stationary combustion turbine is not equipped with an oxidation catalyst then you must petition the Administrator for operating limitations that you will monitor to demonstrate compliance with the formaldehyde emission limitation in Table 1 or petition for approval of no additional operating limitations, and you must not conduct the initial performance test until after the petition has been approved or disapproved by the Administrator",
          "citations": [
            "40 CFR 63.6120(e)"
          ]
        },
        {
          "criterion": "if you petition the Administrator for approval of additional operating limitations then your petition must include identification of the specific parameters, a discussion of the relationship between these parameters and HAP emissions, how you will establish upper and/or lower parameter values, the methods and instruments to measure and monitor the parameters including relative accuracy and precision, and the frequency and methods for recalibrating the instruments",
          "citations": [
            "40 CFR 63.6120(f)"
          ]
        },
        {
          "criterion": "if you petition the Administrator for approval of no additional operating limitations then your petition must identify parameters that could change, discuss any relationship between changes and HAP emissions, explain why establishing numeric limitations is not possible or feasible, describe measurement and monitoring methods and instruments and their accuracy/precision, describe recalibration frequency/methods, and explain why adopting parameters as operating limitations is infeasible, unreasonable, or unnecessary",
          "citations": [
            "40 CFR 63.6120(g)"
          ]
        },
        {
          "criterion": "if you are not using an oxidation catalyst then you must continuously monitor any parameters specified in your approved petition in order to comply with the operating limitations in Table 2 as specified in Table 5 of this subpart",
          "citations": [
            "40 CFR 63.6125(b)"
          ]
        },
        {
          "criterion": "if you are using an oxidation catalyst then you must continuously monitor your catalyst inlet temperature to comply with the operating limitations in Table 2 as specified in Table 5 of this subpart",
          "citations": [
            "40 CFR 63.6125(a)"
          ]
        },
        {
          "criterion": "if you are required to use a continuous monitoring system (CMS) after September 8, 2020 then you must develop and implement a CMS quality control program that includes written procedures per §63.8(d)(1) through (2) and keep those procedures on record",
          "citations": [
            "40 CFR 63.6125(e)"
          ]
        },
        {
          "criterion": "if you are required to conduct performance tests then you must conduct each performance test in Table 3 that applies to you and conduct the tests according to the requirements in Table 3 of this subpart",
          "citations": [
            "40 CFR 63.6120(a)",
            "40 CFR 63.6120(b)"
          ]
        },
        {
          "criterion": "if you are required to conduct performance tests then the tests must be conducted at high load defined as 100 percent plus or minus 10 percent, must consist of three separate test runs each lasting at least 1 hour, and must not be conducted during periods of startup, shutdown, or malfunction with process information recorded to document operating conditions during the test",
          "citations": [
            "40 CFR 63.6120(c)",
            "40 CFR 63.6120(d)"
          ]
        },
        {
          "criterion": "if you are required to comply with the formaldehyde emission limitation and complete a performance test then you must submit a Notification of Compliance Status including the performance test results before the close of business on the 60th calendar day following completion of the performance test",
          "citations": [
            "40 CFR 63.6145(f)"
          ]
        },
        {
          "criterion": "if you are required to conduct initial performance tests or other initial compliance demonstrations then you must conduct them within 180 calendar days after the compliance date specified for your stationary combustion turbine in §63.6095",
          "citations": [
            "40 CFR 63.6110(a)"
          ]
        },
        {
          "criterion": "if you start up a new or reconstructed stationary combustion turbine on or after March 5, 2004 then you must submit an Initial Notification not later than 120 calendar days after you become subject to this subpart",
          "citations": [
            "40 CFR 63.6145(c)"
          ]
        },
        {
          "criterion": "if you are required to conduct an initial performance test then you must submit a notification of intent to conduct the initial performance test at least 60 calendar days before the test is scheduled to begin",
          "citations": [
            "40 CFR 63.6145(e)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm turbine classification: lean premix gas-fired stationary combustion turbine (new or reconstructed) and confirm the startup/date that determines whether it is a 'new or reconstructed' unit",
    "Confirm whether the turbine is equipped with an oxidation catalyst (yes/no)",
    "If no catalyst (your stated case), prepare and file a petition to the Administrator either proposing specific operating limitations to monitor or proposing no additional operating limitations; do not perform the initial performance test until petition is approved or disapproved",
